-- Read-only receipt after the parent commits. A false field is a failed readback.
WITH i AS (SELECT __INPUT__ AS doc,__BINDINGS__ AS bindings),
calls AS (SELECT c->'arguments' AS a FROM i,jsonb_array_elements(coalesce(i.doc->'proposal'->'create_task_calls','[]')) c),
ids AS (SELECT a->>'p_task_id' AS id FROM calls)
SELECT jsonb_build_object(
 'source_head','7a6dcc2084000b4054010d94a04a85a408282497',
 'step',i.doc->>'milestone_id',
 'canonical_tasks_and_arguments_equal',NOT EXISTS(SELECT 1 FROM calls LEFT JOIN control.tasks t ON t.task_id=a->>'p_task_id' WHERE t.task_id IS NULL OR (t.metadata-'planning_storage') IS DISTINCT FROM a->'p_metadata' OR t.metadata->'planning_storage' IS DISTINCT FROM i.doc->'planning_storage' OR t.title IS DISTINCT FROM a->>'p_title' OR t.description IS DISTINCT FROM a->>'p_description' OR t.sequence IS DISTINCT FROM (a->>'p_sequence')::integer OR t.priority IS DISTINCT FROM (a->>'p_priority')::integer OR t.task_type IS DISTINCT FROM a->>'p_task_type' OR t.risk_level IS DISTINCT FROM a->>'p_risk_level' OR t.acceptance_criteria IS DISTINCT FROM a->'p_acceptance_criteria' OR t.verification_plan IS DISTINCT FROM '[]'::jsonb OR t.project_id<>'f71b3b2b-d56b-4f7e-94f5-0b8c379a1088' OR t.workstream_slug<>'doctor-suit' OR t.model_profile<>'no_ai' OR t.retry_policy_id IS NOT NULL),
 'requirements_equal',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(i.doc->'proposal'->'requirements','[]')) x LEFT JOIN control.requirements r ON r.suit_slug='doctor-suit' AND r.requirement_id=x->>'requirement_id' WHERE r.metadata->'canonical_requirement_contract' IS DISTINCT FROM x OR r.title IS DISTINCT FROM x->>'title' OR r.summary IS DISTINCT FROM x->>'summary' OR r.status IS DISTINCT FROM x->>'status'),
 'decisions_equal',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(i.doc->'proposal'->'decisions','[]')) x LEFT JOIN control.decisions d ON d.suit_slug='doctor-suit' AND d.decision_id=x->>'decision_id' WHERE d.metadata->'canonical_decision_contract' IS DISTINCT FROM x OR d.title IS DISTINCT FROM x->>'title' OR d.decision_text IS DISTINCT FROM x->>'decision_text' OR d.status IS DISTINCT FROM x->>'status' OR d.source IS DISTINCT FROM x->>'source'),
 'requirement_links_equal',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text),'[]') FROM (SELECT task_id,suit_slug,requirement_id FROM control.task_requirements WHERE task_id IN(SELECT id FROM ids)) r)=(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM jsonb_array_elements(coalesce(i.doc->'proposal'->'task_requirements','[]')) x),
 'dependency_links_equal',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text),'[]') FROM (SELECT task_id,depends_on_task_id,dependency_type FROM control.task_dependencies WHERE task_id IN(SELECT id FROM ids)) r)=(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM jsonb_array_elements(coalesce(i.doc->'proposal'->'task_dependencies','[]')) x),
 'decision_links_equal',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text),'[]') FROM (SELECT task_id,suit_slug,decision_id,blocking FROM control.task_decisions WHERE task_id IN(SELECT id FROM ids)) r)=(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM jsonb_array_elements(coalesce(i.doc->'proposal'->'task_decisions','[]')) x),
 'nine_open_canonical_start_gates',(SELECT count(*) FROM control.decisions WHERE suit_slug='doctor-suit' AND decision_id LIKE 'DOS-M%-GATE-START' AND status='open')=9 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(i.doc->'all_start_decisions') x LEFT JOIN control.decisions d ON d.suit_slug='doctor-suit' AND d.decision_id=x->>'decision_id' WHERE d.status IS DISTINCT FROM 'open' OR d.metadata->'canonical_decision_contract' IS DISTINCT FROM x),
 'every_task_start_blocked',NOT EXISTS(SELECT 1 FROM control.tasks t WHERE t.suit_slug='doctor-suit' AND NOT EXISTS(SELECT 1 FROM control.task_decisions td JOIN control.decisions d USING(suit_slug,decision_id) WHERE td.task_id=t.task_id AND td.suit_slug='doctor-suit' AND td.decision_id=t.metadata->>'milestone_id'||'-GATE-START' AND td.blocking AND d.status='open')),
 'zero_ready',NOT EXISTS(SELECT 1 FROM control.ready_tasks WHERE suit_slug='doctor-suit'),
 'no_batch_admissions',NOT EXISTS(SELECT 1 FROM control.batch_task_admissions a JOIN control.tasks t USING(task_id) WHERE t.suit_slug='doctor-suit'),
 'no_workflow_claims',NOT EXISTS(SELECT 1 FROM control.workflow_runs WHERE suit_slug='doctor-suit'),
 'no_executions',NOT EXISTS(SELECT 1 FROM control.executions e JOIN control.tasks t USING(task_id) WHERE t.suit_slug='doctor-suit'),
 'no_publication_authority',NOT EXISTS(SELECT 1 FROM control.publication_preexecution_authorizations a JOIN control.tasks t USING(task_id) WHERE t.suit_slug='doctor-suit'),
 'no_task_execution_binding',NOT EXISTS(SELECT 1 FROM control.tasks WHERE suit_slug='doctor-suit' AND (model_profile<>'no_ai' OR retry_policy_id IS NOT NULL OR verification_plan<>'[]'::jsonb)),
 'planned_pending_only',NOT EXISTS(SELECT 1 FROM control.tasks WHERE suit_slug='doctor-suit' AND (status<>'planned' OR engine_stage<>'pending')),
 'project_unchanged',(SELECT to_jsonb(p)-'created_at'-'updated_at' FROM control.projects p WHERE project_id='f71b3b2b-d56b-4f7e-94f5-0b8c379a1088')=i.bindings->'project_snapshot',
 'storage_registration_equal',EXISTS(SELECT 1 FROM control.suits s JOIN control.workstreams w ON w.suit_slug=s.slug WHERE s.slug='doctor-suit' AND s.status='planning' AND s.stack_key='doctor-suit' AND s.app_path IS NULL AND w.project_id='f71b3b2b-d56b-4f7e-94f5-0b8c379a1088' AND w.slug='doctor-suit' AND w.stack_key='doctor-suit' AND w.application_path IS NULL AND NOT w.active AND w.model_profile IS NULL AND w.retry_policy_id IS NULL AND w.verification_config='{}'::jsonb AND w.metadata->'verification_config_proposal'=i.doc->'verification_config_proposal' AND w.metadata->'planning_storage'=i.doc->'planning_storage' AND w.publication_config=i.doc->'publication_config'),
 'expected_counts_match',jsonb_build_object('tasks',(SELECT count(*) FROM control.tasks WHERE suit_slug='doctor-suit'),'requirements',(SELECT count(*) FROM control.requirements WHERE suit_slug='doctor-suit'),'decisions',(SELECT count(*) FROM control.decisions WHERE suit_slug='doctor-suit'))=i.doc->'expected_counts',
 'task_count',(SELECT count(*) FROM control.tasks WHERE suit_slug='doctor-suit')
) AS readback_receipt FROM i;
